// dirtysdk lobby -- LobbyNameCmp @0x82B10050 (ledger TU vendor:ea-dirtysdk).
//
// Table-driven player-name comparator: each byte is mapped through a 128-entry
// translation table; mapped value 1 means "skip this byte" (controls + space + DEL),
// 0 terminates, lowercase letters map onto uppercase, everything else printable maps
// to itself. The first differing mapped pair decides the result (strcmp convention).
//
// The table is the .rdata block at 0x82146038, dumped 2026-08-26 from the decrypted
// ARTIST basefile (scratch\postfx_step9_final\envfix\work\image.bin, offset 0x146038).
//
// X360 QUIRK, deliberately NOT reproduced: the PPC body indexes the table with a
// SIGN-EXTENDED byte (extsb at 0x82B10060/0x82B10078), so input bytes >= 0x80 read
// unrelated .rdata BEFORE the table (dumped: pointer values and the "CsisAlloc"
// literal). Player names are 7-bit ASCII so that lane never runs on real data; this
// body maps high-bit bytes to 1 (skip) instead of reproducing an out-of-bounds read.

#include "lobbyname.h"

static const unsigned char _LobbyName_aXlatTable[128] =
{
    // 0x00: NUL terminates; 0x01..0x20 (controls + space) are skipped.
    0x00, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01,
    0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01,
    0x01, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27, 0x28, 0x29, 0x2A, 0x2B, 0x2C, 0x2D, 0x2E, 0x2F,
    0x30, 0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x38, 0x39, 0x3A, 0x3B, 0x3C, 0x3D, 0x3E, 0x3F,
    0x40, 0x41, 0x42, 0x43, 0x44, 0x45, 0x46, 0x47, 0x48, 0x49, 0x4A, 0x4B, 0x4C, 0x4D, 0x4E, 0x4F,
    0x50, 0x51, 0x52, 0x53, 0x54, 0x55, 0x56, 0x57, 0x58, 0x59, 0x5A, 0x5B, 0x5C, 0x5D, 0x5E, 0x5F,
    // 0x61..0x7A ('a'..'z') fold onto 'A'..'Z'; 0x7F (DEL) is skipped.
    0x60, 0x41, 0x42, 0x43, 0x44, 0x45, 0x46, 0x47, 0x48, 0x49, 0x4A, 0x4B, 0x4C, 0x4D, 0x4E, 0x4F,
    0x50, 0x51, 0x52, 0x53, 0x54, 0x55, 0x56, 0x57, 0x58, 0x59, 0x5A, 0x7B, 0x7C, 0x7D, 0x7E, 0x01,
};

extern "C" int LobbyNameCmp(const char* pName1, const char* pName2)
{
    for (;;)
    {
        int iChar1;
        int iChar2;
        do
        {
            const unsigned char uRaw = (unsigned char)*pName1++;
            iChar1 = (uRaw < 0x80) ? _LobbyName_aXlatTable[uRaw] : 1;
        }
        while (iChar1 == 1);
        do
        {
            const unsigned char uRaw = (unsigned char)*pName2++;
            iChar2 = (uRaw < 0x80) ? _LobbyName_aXlatTable[uRaw] : 1;
        }
        while (iChar2 == 1);

        const int iDiff = iChar1 - iChar2;
        if (iDiff != 0)
        {
            return iDiff;
        }
        if (iChar1 == 0)
        {
            return 0;
        }
    }
}
